export const CREATIVE_THINKING_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu berpikir kreatif",q:"Dalam memecahkan masalah, 'berpikir kreatif' terutama berarti...",options:["Menghasilkan ide atau sudut pandang baru yang tidak langsung terpikir","Menggambar dengan rapi sehingga hasil gambarnya dipuji guru dan teman","Menjawab secepatnya tanpa berpikir panjang, sebab jawaban pertama paling kreatif"],answer:0,explain:"Berpikir kreatif adalah kemampuan melihat masalah dengan cara baru dan memunculkan pilihan yang tidak biasa — bukan soal bakat seni.",hint:"Apa yang membedakan ide 'baru' dari ide 'yang pertama muncul'?"},
{n:2,type:"mcq",micro:"Banyak jawaban benar",q:"Untuk 'sebutkan kegunaan sebuah klip kertas', pertanyaan ini...",options:["Punya satu jawaban benar saja, yaitu menjepit kertas, sedangkan fungsi lain dianggap salah","Punya banyak jawaban mungkin — penjepit, penanda buku, pembuka kartu SIM, kail kecil, dll.","Tidak bisa dijawab, karena benda sekecil itu tidak memiliki kegunaan selain yang tertulis"],answer:1,explain:"Soal terbuka mengundang banyak jawaban. Berpikir kreatif nyaman dengan 'lebih dari satu jawaban'.",hint:"Berapa banyak cara berbeda kamu bisa memakai satu benda kecil?"},
{n:3,type:"mcq",micro:"Berpikir menyebar",q:"'Berpikir menyebar' (divergen) berarti...",options:["Mempersempit semua pilihan ke satu jawaban secepat mungkin","Berhenti berpikir begitu menemukan jawaban yang masuk akal","Menghasilkan sebanyak mungkin kemungkinan dari satu titik awal"],answer:2,explain:"Berpikir divergen membuka pilihan; kebalikannya, berpikir konvergen, menyaring dan memilih. Keduanya dibutuhkan.",hint:"Melebar dulu atau menyempit dulu?"},
{n:4,type:"mcq",micro:"Menantang asumsi",q:"Masalah: 'antrean pengambilan rapor terlalu panjang'. Asumsi tersembunyi yang bisa ditantang:",options:["'Rapor harus diambil orang tua secara langsung di sekolah pada hari yang sama'","'Rapor adalah dokumen penting yang memuat nilai siswa selama satu semester'","'Sekolah memiliki gedung, ruang kelas, dan halaman yang cukup luas untuk acara itu'"],answer:0,explain:"Menantang asumsi ('harus langsung', 'harus hari yang sama') membuka solusi baru: janji temu bertahap, kirim digital, ambil di beberapa hari.",hint:"Apa yang kita anggap 'sudah pasti begitu' padahal bisa diubah?"},
{n:5,type:"tf",micro:"Ide pertama bukan batas",q:"Benar atau Salah: Berhenti pada ide pertama yang 'cukup masuk akal' sering membuat kita melewatkan ide yang lebih baik atau lebih sederhana.",answer:true,explain:"Ide pertama biasanya yang paling jelas, bukan yang paling baik. Meluangkan waktu untuk beberapa ide lagi sering berbuah.",hint:"Apakah pilihan pertama di rak selalu yang terbaik?"},
{n:6,type:"mcq",micro:"Menunda penilaian",q:"Saat mencoba menghasilkan ide kreatif, mengapa berguna menunda menilai 'ini bagus atau jelek'?",options:["Ide yang jelek perlu dibuang saat itu juga supaya daftar ide tidak dipenuhi hal yang tak berguna","Penilaian dini membuat kita menolak ide yang belum matang, padahal ide itu bisa dikembangkan","Penilaian itu merusak tahap awal, sehingga sebaiknya tidak dilakukan di tahap mana pun"],answer:1,explain:"Fase menghasilkan dan fase menilai bekerja lebih baik bila dipisah. Nilai belakangan, saat ide sudah banyak.",hint:"Apa yang terjadi pada benih ide kalau langsung diinjak?"},
{n:7,type:"mcq",micro:"Melihat dari sisi lain",q:"'Bagaimana kalau kita lihat dari sudut pandang si adik kelas / si penjaga kantin / si orang tua?' adalah teknik...",options:["Menyalahkan pihak lain atas masalah yang terjadi agar kita tidak perlu mengubah cara berpikir kita","Menghindari masalah yang sulit dengan memilih topik lain yang lebih nyaman dan sudah dikenal","Berganti perspektif untuk menemukan kebutuhan dan ide yang tidak terlihat dari posisi kita sendiri"],answer:2,explain:"Tiap peran melihat masalah berbeda. Meminjam sudut pandang mereka memunculkan ide baru.",hint:"Apa yang penting bagi orang lain yang mungkin tidak kamu pikirkan?"},
{n:8,type:"order",micro:"Dari masalah ke ide kreatif",q:"Urutkan langkah menghasilkan ide kreatif untuk sebuah masalah.",items:["Pahami masalah dan tuliskan asumsi yang kamu bawa","Tantang atau balik beberapa asumsi itu","Hasilkan banyak ide, termasuk yang aneh, tanpa menilai","Baru kemudian saring dan kembangkan ide yang menjanjikan"],answer:[0,1,2,3],explain:"Pahami & sadari asumsi → tantang asumsi → hasilkan banyak ide → saring & kembangkan.",hint:"Kamu perlu tahu asumsimu sebelum bisa menantangnya."},
{n:9,type:"mcq",micro:"Ide aneh sebagai batu loncatan",q:"Untuk 'mengurangi buku yang hilang di perpustakaan', ada usul 'rantai semua buku ke rak'. Ide ini tidak dipakai, tapi memicu...",options:["'Bagaimana kalau buku 'menandai dirinya' saat keluar?' → sistem daftar pinjam sederhana di pintu","Berarti buku-buku harus dirantai ke rak supaya tidak ada lagi yang bisa membawanya pulang","Ide itu aneh dan tidak berguna, sehingga tak mungkin memicu gagasan lain yang lebih masuk akal"],answer:0,explain:"Ide ekstrem sering mengandung inti ('buku harus ketahuan saat keluar') yang bisa diwujudkan dengan cara yang wajar.",hint:"Apa keinginan di balik 'merantai buku'?"},
{n:10,type:"mcq",micro:"Menggabungkan dua hal",q:"Teknik kreatif 'gabungkan yang tidak biasa': 'jam dinding' + 'jadwal piket' menjadi...",options:["Tidak bisa digabung, sebab jam hanya untuk waktu dan piket urusan lain","Jam piket: penanda bergerak menunjukkan kelompok yang bertugas hari ini","Dua benda terpisah, jam di dinding dan daftar piket di papan tulis"],answer:1,explain:"Menggabungkan dua benda/ide yang biasanya tidak bersama sering menghasilkan solusi segar.",hint:"Apa jadinya kalau fungsi 'menunjukkan waktu' digabung 'menunjukkan giliran'?"},
{n:11,type:"mcq",micro:"Kuantitas memicu kualitas",q:"Mengapa mengejar 20 ide sering menghasilkan ide bagus dibanding berhenti di 3?",options:["Ide yang muncul makin jelek seiring bertambahnya jumlah, sehingga tiga ide pertama yang terbaik","Tiga ide merupakan batas yang bisa dihasilkan otak manusia dalam satu sesi berpikir","Ide ke-1 sampai 5 biasanya 'yang sudah ada di permukaan'; ide segar muncul setelah itu"],answer:2,explain:"Ide-ide awal adalah yang paling mudah diakses. Mendorong lebih jauh memaksa pikiran mencari yang tidak biasa.",hint:"Kapan ide yang benar-benar baru biasanya muncul?"},
{n:12,type:"mcq",micro:"Kreativitas butuh keberanian salah",q:"Rasa takut 'idekku terdengar bodoh' menghambat kreativitas karena...",options:["Kita menyensor ide sebelum diucapkan, termasuk yang sebenarnya bagus","Ide yang terdengar bodoh memang perlu disensor sejak awal sesi","Rasa takut membantu kita berpikir karena hanya memilih ide yang aman"],answer:0,explain:"Banyak ide bagus terdengar aneh pada awalnya. Ruang yang aman untuk 'ide setengah jadi' penting.",hint:"Apa yang hilang kalau semua orang hanya berani mengucapkan ide yang 'pasti aman'?"},
{n:13,type:"tf",micro:"Kreativitas bisa dilatih",q:"Benar atau Salah: Berpikir kreatif adalah bakat tetap sejak lahir; latihan dan teknik tidak bisa meningkatkannya.",answer:false,explain:"Seperti otot, kreativitas menguat dengan latihan: menantang asumsi, berganti perspektif, menggabungkan ide, dan berlatih menahan penilaian.",hint:"Apakah orang menjadi lebih kreatif setelah banyak berlatih menghasilkan ide?"},
{n:14,type:"mcq",micro:"Alternatif untuk keputusan hitam-putih",q:"Kelas terbelah: 'wisata ke museum' atau 'wisata ke pantai'. Berpikir alternatif menanyakan...",options:["Batalkan saja wisata kelas itu, karena kedua pilihan tempat sama-sama punya kekurangan yang cukup berat","'Adakah pilihan ketiga yang belum kita pikirkan?' — misalnya tempat yang punya keduanya, atau dua kegiatan kecil","Pilih tempat yang paling banyak suaranya setelah pemungutan suara, lalu hentikan pembahasan lainnya"],answer:1,explain:"Saat pilihan terasa hanya dua, sering ada opsi ketiga yang menggabungkan atau melampaui keduanya.",hint:"Apakah benar-benar hanya ada dua kemungkinan?"},
{n:15,type:"mcq",micro:"Membingkai ulang masalah",q:"Masalah 'kelas terlalu berisik saat kerja kelompok' dibingkai ulang menjadi 'kelas belum punya cara mengatur suara saat semua bicara sekaligus'. Efeknya:",options:["Tidak mengubah apa-apa pada ide yang muncul, karena kalimat masalahnya tetap sama maknanya dengan yang lama","Membuat masalah menjadi lebih besar dan lebih sulit, sehingga hanya orang dewasa yang bisa memikirkannya","Membuka ide seperti 'sinyal tangan untuk pelankan suara', 'zona bicara & zona diam', bukan hanya 'suruh diam'"],answer:2,explain:"Mengubah kata-kata masalah mengubah jenis solusi yang terpikir.",hint:"'Suruh diam' vs 'atur suara bersama' — solusi mana yang berbeda?"},
{n:16,type:"mcq",micro:"Ide dari batasan",q:"Batasan 'anggaran nol' untuk menghias kelas justru bisa memicu...",options:["Ide kreatif: pakai karya siswa, barang bekas, tanaman dari rumah, tata ulang yang ada","Dianggap buntu, sebab tanpa dana kelas tidak mungkin dibuat menarik dan nyaman","Menyerah menghias kelas dan menunggu bantuan dana dari sekolah tahun depan"],answer:0,explain:"Batasan mempersempit ruang sehingga otak dipaksa menemukan jalan tidak biasa. 'Bebas apa saja' kadang malah membingungkan.",hint:"Lebih mudah berkreasi dengan 'buat apa saja' atau 'buat dari 3 barang ini'?"},
{n:17,type:"mcq",micro:"Menahan 'itu tidak akan berhasil'",q:"Dalam sesi ide, respons yang menjaga aliran kreativitas:",options:["'Idemu kurang bagus, lebih baik pakai ide saya' — mengalahkan ide teman","'Ya, dan bagaimana kalau kita tambah...' — mengembangkan ide teman","'Itu tidak akan berhasil, coba ide yang lain' — menolak ide teman"],answer:1,explain:"'Ya, dan...' membangun; 'ya, tapi...' dan penolakan langsung memadamkan. Penilaian mendapat gilirannya sendiri nanti.",hint:"Mana yang menambah bahan bakar ke ide, mana yang memadamkan?"},
{n:18,type:"mcq",micro:"Istirahat membantu",q:"Sering ide bagus muncul saat kita berhenti sejenak (jalan-jalan, mandi) setelah berpikir keras. Ini karena...",options:["Ide datang dari luar ketika kita melamun, sehingga berpikir sebelumnya tidak berhubungan","Berpikir keras tidak berguna, karena ide bagus hanya muncul secara kebetulan saat bersantai","Pikiran terus mengolah masalah di latar belakang; jeda memberi ruang koneksi baru terbentuk"],answer:2,explain:"Setelah 'mengisi' pikiran dengan masalah, jeda sering memunculkan wawasan. Berpikir dan beristirahat keduanya bagian dari prosesnya.",hint:"Pernahkah jawaban muncul justru saat kamu tidak sedang memikirkannya?"},
{n:19,type:"mcq",micro:"Kreatif tapi tetap layak",q:"Ide kreatif menjadi solusi ketika...",options:["Selain baru, ia juga bisa dijalankan dengan sumber daya nyata dan benar-benar mengatasi masalah","Cukup terdengar keren dan mengesankan di telinga orang lain, walau tidak bisa dijalankan","Paling aneh di antara semua ide yang dikumpulkan, karena ide teraneh dianggap paling kreatif"],answer:0,explain:"Kreativitas tanpa kelayakan hanya khayalan; kelayakan tanpa kreativitas kadang tidak menyelesaikan masalah. Titik temunya yang dicari.",hint:"Apa gunanya ide brilian yang mustahil dilakukan?"},
{n:20,type:"open",micro:"Latihan menantang asumsi",q:"Masalah: 'Siswa sulit menemukan barang yang tertinggal/hilang di sekolah.' Tuliskan minimal 4 asumsi yang biasanya kita bawa tentang masalah ini, lalu untuk setiap asumsi tuliskan satu ide yang muncul kalau asumsi itu dibalik.",explain:"Jawaban baik menyebut asumsi yang benar-benar bisa ditantang (bukan fakta keras) dan menurunkan ide konkret dari pembalikannya.",hint:"Cari kalimat 'harus...' atau 'hanya bisa...' dalam cara kamu memikirkan masalah ini.",sample:"Asumsi 1: 'barang hilang harus dicari sendiri satu per satu' → balik: buat satu titik 'kotak barang temuan' terpusat + jadwal pengumuman mingguan. Asumsi 2: 'pemilik yang harus mencari' → balik: penemu yang wajib menyerahkan ke pos + foto ditempel di papan. Asumsi 3: 'barang tidak bisa 'memanggil' pemiliknya' → balik: minta siswa menuliskan nama+kelas di barang penting, atau tempel stiker kode. Asumsi 4: 'pencarian hanya bisa lewat mata' → balik: papan/grup digital 'kehilangan & penemuan' dengan deskripsi. Asumsi 5: 'ini masalah individu' → balik: jadikan tugas piket mingguan mengelola kotak barang temuan."},
{n:21,type:"mcq",micro:"SCAMPER: Substitusi",q:"Teknik SCAMPER huruf 'S' (Substitute/Ganti): untuk 'tas sekolah terlalu berat', menerapkan 'ganti' berarti...",options:["Tidak membawa apa-apa ke sekolah, lalu menyalin pelajaran dari ingatan teman yang kebetulan membawa buku lengkap","Ganti buku tebal dengan salinan bab yang dipakai / ganti bahan tas dengan yang lebih ringan / ganti membawa semua jadi loker","Buang saja tasnya dan minta pihak sekolah menyediakan semua perlengkapan belajar tanpa dibawa dari rumah"],answer:1,explain:"'Ganti' menanyakan: bahan apa, langkah apa, komponen apa yang bisa diganti dengan sesuatu yang lebih baik?",hint:"Apa yang bisa ditukar dengan versi yang lebih ringan?"},
{n:22,type:"mcq",micro:"SCAMPER: Kombinasi",q:"Huruf 'C' (Combine/Gabungkan): untuk 'terlalu banyak alat tulis berserakan', 'gabungkan' menghasilkan...",options:["Beli lebih banyak alat tulis lagi supaya ada banyak cadangan, lalu simpan di berbagai tempat yang berbeda di dalam kelas","Larang siswa membawa alat tulis ke sekolah dan wajibkan memakai alat milik kelas, supaya lantai tidak berserakan","Satu tempat pensil multifungsi / gabungkan penggaris+busur+pensil jadi satu set / gabungkan tugas piket alat tulis dengan piket kebersihan"],answer:2,explain:"'Gabungkan' menanyakan: apa yang bisa disatukan — fungsi, benda, langkah, atau orang?",hint:"Dua hal apa yang lebih baik jadi satu?"},
{n:23,type:"mcq",micro:"SCAMPER: Adaptasi",q:"Huruf 'A' (Adapt/Sesuaikan): meniru ide dari tempat lain dan menyesuaikannya. Untuk 'antre kantin kacau', adaptasi dari...",options:["Sistem nomor antrean bank / jalur cepat minimarket / pemesanan sebelumnya seperti kantin sekolah lain","Tidak ada hal yang bisa ditiru dari tempat lain, karena kantin sekolah berbeda dari tempat lainnya","Adaptasi berarti menyalin persis sama tanpa mengubah apa-apa, walau keadaan kantin sekolah berbeda"],answer:0,explain:"'Sesuaikan' menanyakan: siapa lagi yang sudah menyelesaikan masalah mirip, dan bagaimana caranya bisa disesuaikan ke sini?",hint:"Di mana lagi orang mengatur banyak orang yang menunggu dilayani?"},
{n:24,type:"mcq",micro:"SCAMPER: Modifikasi",q:"Huruf 'M' (Modify/Ubah — perbesar atau perkecil): untuk 'papan pengumuman jarang dibaca', modifikasi berarti...",options:["Biarkan saja papan itu di tempatnya semula, sebab siswa yang berminat akan mencari sendiri isi pengumumannya","Perbesar & pindahkan ke jalur yang pasti dilewati / perkecil isinya jadi 3 poin penting saja / ubah warnanya mencolok","Hapus papannya dan hentikan pengumuman tertulis, sebab siswa sekarang malas membaca tulisan di dinding"],answer:1,explain:"'Ubah' menanyakan: apa yang terjadi kalau bagian ini dibuat jauh lebih besar, lebih kecil, lebih sering, atau lebih menonjol?",hint:"Apa yang berubah kalau ukurannya, letaknya, atau seringnya diubah drastis?"},
{n:25,type:"mcq",micro:"SCAMPER: Pakai untuk hal lain",q:"Huruf 'P' (Put to another use): sisa kertas ujian yang tercetak satu sisi bisa...",options:["Hanya bisa dibuang ke tempat sampah karena fungsinya sudah habis total","Tidak ada gunanya lagi, kecuali jika dijual kembali ke tempat daur ulang","Dijadikan kertas buram/coretan, kertas origami, bahan mading, atau blok memo"],answer:2,explain:"'Pakai untuk hal lain' menanyakan: adakah kegunaan baru untuk benda/langkah/orang yang biasanya dianggap selesai atau tidak berguna?",hint:"Apa lagi yang bisa dilakukan dengan 'limbah' ini?"},
{n:26,type:"classify",micro:"Mencocokkan teknik SCAMPER",q:"Cocokkan tiap ide untuk 'membuat kegiatan olahraga pagi lebih diminati' dengan tekniknya: 'Ganti', 'Eliminasi (hilangkan)', atau 'Balik (Reverse)'.",items:["Ganti lari monoton dengan permainan gerak berkelompok","Hilangkan bagian pemanasan panjang yang membosankan, gabung ke permainannya","Alih-alih guru memimpin, giliran tiap kelompok merancang dan memimpin sesi"],groups:["Ganti","Eliminasi (hilangkan)","Balik (Reverse)"],answer:{"Ganti":["Ganti lari monoton dengan permainan gerak berkelompok"],"Eliminasi (hilangkan)":["Hilangkan bagian pemanasan panjang yang membosankan, gabung ke permainannya"],"Balik (Reverse)":["Alih-alih guru memimpin, giliran tiap kelompok merancang dan memimpin sesi"]},explain:"Ganti = tukar satu elemen; Eliminasi = buang elemen; Balik = tukar urutan/peran/arah.",hint:"Apakah ide ini menukar, membuang, atau membalik sesuatu?"},
{n:27,type:"mcq",micro:"SCAMPER: Eliminasi",q:"Huruf 'E' (Eliminate/Hilangkan): untuk 'proses pendaftaran ekskul berbelit', eliminasi berarti...",options:["Hilangkan langkah/formulir yang tidak benar-benar dipakai; sisakan yang minimum","Hilangkan kegiatan ekskulnya supaya urusan administrasi menjadi sederhana","Tambah lebih banyak langkah pemeriksaan supaya setiap data dijamin benar"],answer:0,explain:"'Hilangkan' menanyakan: bagian mana yang bisa dibuang tanpa merusak inti — sering menyederhanakan secara drastis.",hint:"Langkah mana yang tidak ada yang benar-benar memakai hasilnya?"},
{n:28,type:"mcq",micro:"Analogi jauh",q:"Untuk 'menyebarkan info penting agar tidak ada yang terlewat', meminjam dari 'bagaimana sarang lebah mengabari lokasi bunga' bisa memicu...",options:["Meniru lebah secara harfiah: tiap siswa memakai kostum, berdengung, dan menari memutar di depan kelas tiap pagi","Sistem 'penari lebah': beberapa 'pembawa pesan' yang aktif menyampaikan ke kelompoknya, bukan hanya menempel pengumuman pasif","Tidak relevan, sebab lebah hidup di alam sedangkan pengumuman sekolah hanya perlu diurus oleh guru piket"],answer:1,explain:"Analogi dari bidang jauh (alam, olahraga, memasak) sering memberi struktur solusi yang segar.",hint:"Bagaimana sistem lain menyelesaikan 'menyampaikan info ke semua anggota'?"},
{n:29,type:"tf",micro:"Teknik memaksa koneksi baru",q:"Benar atau Salah: Teknik seperti kata pemicu acak atau analogi jauh tidak ada gunanya karena otak paling kreatif saat dibiarkan berpikir langsung tanpa gangguan.",answer:false,explain:"Pikiran cenderung mengikuti jalur yang sudah dikenal. Rangsangan yang 'dipaksakan' seperti kata acak justru membuka jalur koneksi yang tidak akan terbentuk lewat pemikiran langsung.",hint:"Mengapa memakai kata acak yang tidak berhubungan bisa membantu?"},
{n:30,type:"order",micro:"Menerapkan satu putaran SCAMPER",q:"Urutkan langkah memakai SCAMPER pada sebuah masalah.",items:["Nyatakan masalah & elemen-elemennya (bahan, langkah, orang, urutan)","Untuk tiap huruf SCAMPER, ajukan pertanyaannya dan catat ide yang muncul","Kumpulkan semua ide tanpa menilai","Pilih & kembangkan 2–3 ide paling menjanjikan"],answer:[0,1,2,3],explain:"Uraikan elemen → jalankan tiap huruf → kumpulkan ide → saring & kembangkan.",hint:"Kamu perlu tahu elemen masalahnya sebelum bisa 'mengganti' atau 'menghilangkan' elemen."},
{n:31,type:"mcq",micro:"Ide dari 'bagaimana kalau ekstrem'",q:"Pertanyaan 'bagaimana kalau kita punya waktu tak terbatas' lalu 'bagaimana kalau hanya 5 menit' untuk masalah yang sama...",options:["Membuang waktu kelompok, sebab versi ekstrem tidak mungkin dipakai dan hanya membuat peserta bingung","Hanya versi 'tak terbatas' yang berguna, sedangkan versi waktu singkat hanya menghasilkan ide yang dangkal","Memunculkan ide berbeda di tiap ekstrem; versi '5 menit' sering menghasilkan solusi yang sangat sederhana dan langsung"],answer:2,explain:"Mendorong ke ekstrem (waktu, biaya, jumlah) memaksa pemikiran keluar dari zona nyaman.",hint:"Solusi apa yang muncul kalau kamu HANYA punya 5 menit?"},
{n:32,type:"mcq",micro:"Menggambar ide",q:"Menggambar sketsa kasar sebuah ide (bukan hanya menulisnya) berguna karena...",options:["Memaksa memikirkan bagaimana ide bekerja secara nyata, dan sering memunculkan pertanyaan/ide baru","Menghabiskan waktu kelompok karena gambar tidak mengubah isi ide yang sudah dipikirkan sebelumnya","Hanya untuk siswa yang pandai seni, sebab gambar yang jelek membuat ide tampak buruk di mata kelompok"],answer:0,explain:"Membuat ide 'terlihat' — sketsa, model, purwarupa kertas — mengungkap detail dan celah yang tidak kelihatan dari kata-kata.",hint:"Apa yang kamu sadari saat mencoba menggambar cara sesuatu bekerja?"},
{n:33,type:"mcq",micro:"Ide dari kesalahan/kecelakaan",q:"Beberapa penemuan terkenal (lem tempel-lepas, dll.) berasal dari 'kesalahan'. Pelajaran untuk berpikir kreatif:",options:["Hanya rencana sempurna tanpa kesalahan yang bisa menghasilkan penemuan berguna","Hasil yang tidak diharapkan patut diperhatikan — mungkin berguna untuk masalah lain","Kesalahan tidak berguna dan harus segera dibuang, sehingga tak perlu diperhatikan lagi"],answer:1,explain:"Sikap terbuka terhadap 'hasil aneh' — bertanya 'untuk apa ini bisa berguna?' — adalah kebiasaan kreatif.",hint:"Apa yang kamu lakukan saat percobaan memberi hasil yang tidak kamu duga?"},
{n:34,type:"mcq",micro:"Ide bersama kelompok beragam",q:"Curah gagasan dengan orang dari kelas, usia, atau minat berbeda cenderung...",options:["Menghasilkan ide yang seragam karena anggota akhirnya mengikuti pendapat yang paling keras","Mengurangi jumlah ide karena anggota saling menunggu dan enggan memulai lebih dulu","Menghasilkan ragam ide lebih luas karena tiap orang 'melihat' masalah secara berbeda"],answer:2,explain:"Keberagaman peserta memperluas ruang ide. Orang yang berpikir mirip menghasilkan ide yang mirip.",hint:"Apakah 5 orang berpikiran sama seluas 5 orang berpikiran berbeda?"},
{n:35,type:"mcq",micro:"Membangun di atas 'ide gila'",q:"Ide: 'siswa mengajar guru'. Terdengar terbalik, tapi bisa dikembangkan menjadi...",options:["Sesi 'siswa berbagi keterampilan' (teknologi, bahasa gaul, minat) — memanfaatkan pengetahuan yang tidak dimiliki guru","Ide itu harus dibuang karena guru adalah orang yang mengajar dan murid tidak mungkin tahu lebih banyak","Guru berhenti mengajar dan seluruh pelajaran diserahkan kepada siswa tanpa bimbingan orang dewasa di kelas"],answer:0,explain:"Ide yang membalik peran sering mengandung wawasan yang bisa diwujudkan dalam bentuk yang masuk akal.",hint:"Apa hal berharga yang siswa tahu tapi guru tidak?"},
{n:36,type:"mcq",micro:"Kreativitas vs kebiasaan",q:"'Kita selalu melakukannya begini' adalah tanda...",options:["Tidak perlu dipikirkan lagi, karena kebiasaan yang sudah lama dilakukan sulit diperbaiki","Ada peluang untuk bertanya 'apakah cara ini masih yang terbaik, atau hanya kebiasaan?'","Cara itu yang terbaik, sebab sudah dipakai begitu lama oleh banyak orang tanpa keluhan"],answer:1,explain:"Kebiasaan menghemat pikiran, tapi juga menyembunyikan cara yang lebih baik. Sesekali menantangnya menyegarkan.",hint:"Apakah cara lama dipakai karena terbaik, atau karena tidak pernah ditinjau?"},
{n:37,type:"tf",micro:"Ide harus 'mengendap' dulu",q:"Benar atau Salah: Kalau sebuah ide terlihat biasa saat pertama kali muncul, itu sudah pasti ide yang lemah dan aman untuk langsung dibuang.",answer:false,explain:"Ide yang tampak biasa kadang menjadi menarik setelah dikembangkan, digabung dengan ide lain, atau dilihat lagi keesokan harinya. Menilai terlalu cepat berisiko membuang potensi.",hint:"Apakah semua ide bagus terlihat bagus sejak detik pertama?"},
{n:38,type:"mcq",micro:"Membatasi kreativitas dengan kriteria",q:"Setelah menghasilkan banyak ide, kriteria ('gratis', 'aman', 'muat 15 menit') dipakai untuk...",options:["Menghukum ide kreatif yang aneh agar tak ada yang berani mengajukan gagasan tak biasa","Menghentikan semua ide yang muncul, lalu memulai sesi baru dari awal tanpa catatan","Menyaring ke ide yang bisa benar-benar dipakai — fase menyempit setelah fase melebar"],answer:2,explain:"Kreativitas butuh dua fase: melebar (semua ide) lalu menyempit (saring dengan kriteria). Kriteria dipakai SETELAH menghasilkan.",hint:"Kapan kriteria dipakai — saat menghasilkan ide atau saat memilih?"},
{n:39,type:"mcq",micro:"Ide yang menyelesaikan beberapa masalah sekaligus",q:"Ide 'sudut baca dengan tanaman' bisa dinilai lebih tinggi kalau ternyata juga...",options:["Menyelesaikan masalah lain: kelas terasa lebih sejuk & hidup, ada tugas merawat tanaman untuk piket","Hanya menyelesaikan satu hal, yaitu menutupi dinding kosong, tanpa memberi manfaat tambahan bagi kelas","Menambah masalah baru, karena tanaman mengotori lantai kelas dan merepotkan petugas kebersihan"],answer:0,explain:"Ide kreatif yang menyentuh beberapa kebutuhan sekaligus sering merupakan pilihan yang sangat bernilai.",hint:"Apa lagi hal baik yang ikut terjadi kalau ide ini dipakai?"},
{n:40,type:"open",micro:"Menerapkan SCAMPER",q:"Masalah: 'Jadwal pelajaran di papan sering tidak diperhatikan sehingga siswa salah bawa buku.' Jalankan minimal 4 huruf SCAMPER (Ganti, Gabungkan, Sesuaikan, Ubah, Pakai-untuk-hal-lain, Hilangkan, Balik) dan hasilkan minimal 6 ide. Tandai huruf untuk tiap ide.",explain:"Jawaban baik menjalankan 4+ huruf secara eksplisit dan menghasilkan 6+ ide beragam dengan huruf ditandai.",hint:"Uraikan dulu elemen masalah (papan, waktu cek, buku, orang), lalu terapkan tiap huruf.",sample:"Ganti: ganti papan tulis manual dengan kartu jadwal warna yang dibawa pulang tiap siswa. Gabungkan: gabungkan info jadwal ke grup pengumuman + tempel di pintu keluar (dilihat saat pulang). Sesuaikan: tiru 'papan keberangkatan bandara' — jadwal besok ditayangkan/ditulis mencolok setiap sore. Ubah: perbesar dan pindahkan papan ke tempat yang PASTI dilewati (dekat rak tas). Pakai-untuk-hal-lain: sampul buku tulis dicetak jadwal mingguan. Hilangkan: hilangkan kebutuhan mengecek harian — sepakati 'set buku tetap per hari' yang tidak berubah. Balik: alih-alih siswa mengecek papan, ketua kelompok mengumumkan '3 buku besok' setiap sore."},
{n:41,type:"mcq",micro:"Divergen lalu konvergen",q:"Proses kreatif yang sehat berbentuk...",options:["Terus melebar tanpa akhir sampai ide-ide yang terkumpul mencapai jumlah ratusan","Melebar (hasilkan banyak) lalu menyempit (saring & pilih), kadang beberapa putaran","Langsung menyempit ke satu ide sejak awal, lalu melebar hanya jika ide itu gagal"],answer:1,explain:"Bergantian antara membuka pilihan dan menyaringnya — kadang berulang — adalah pola inti berpikir kreatif yang produktif.",hint:"Apa dua gerakan yang bergantian dalam proses kreatif?"},
{n:42,type:"mcq",micro:"Mengembangkan ide mentah",q:"Ide mentah 'lomba kebersihan antar kelompok' dikembangkan dengan menanyakan...",options:["Tidak perlu detail, sebab kreativitas peserta akan menutupi aturan lomba yang masih belum jelas","Cukup umumkan saja lombanya lalu biarkan peserta menafsirkan sendiri semua aturan dan cara penilaiannya","Bagaimana persisnya dinilai? Seberapa sering? Hadiahnya apa? Siapa jurinya? Bagaimana mencegah kecurangan?"],answer:2,explain:"Ide menjadi solusi setelah pertanyaan 'bagaimana persisnya' dijawab. Pengembangan mengubah arah menjadi rencana.",hint:"Detail apa yang harus diisi agar ide bisa dijalankan?"},
{n:43,type:"mcq",micro:"Purwarupa (prototipe)",q:"Membuat versi kecil/kasar dari ide (papan jadwal contoh, satu kartu antrean) sebelum membuat yang lengkap berguna untuk...",options:["Menguji apakah ide bekerja dan mendapat umpan balik dengan biaya rendah, lalu memperbaiki","Membuang bahan dengan percuma karena purwarupa pada akhirnya akan dibuang ke tempat sampah","Membuat ide terlihat resmi dan meyakinkan di depan guru yang akan menilai hasilnya"],answer:0,explain:"Purwarupa mengubah ide dari 'kata-kata' menjadi 'sesuatu yang bisa dicoba dan dikomentari orang'.",hint:"Bagaimana kamu menguji ide tanpa membangun versi penuhnya dulu?"},
{n:44,type:"mcq",micro:"Menggabungkan kreatif dan kritis",q:"Peran berpikir kritis dalam proses kreatif adalah...",options:["Tidak ada perannya dalam proses kreatif, karena kreativitas sebaiknya bebas dari penilaian","Menilai dan menyaring ide SETELAH cukup banyak dihasilkan — bukan mematikannya saat baru muncul","Menolak setiap ide baru sejak awal agar kelompok hanya memegang ide yang sudah terbukti"],answer:1,explain:"Kreatif dan kritis adalah pasangan: kreatif menghasilkan, kritis menyaring. Masalahnya hanya kalau kritis datang terlalu dini.",hint:"Kapan penilaian membantu, dan kapan ia merusak?"},
{n:45,type:"mcq",micro:"Ide yang menantang batasan yang salah",q:"Batasan 'kita hanya boleh pakai ruang kelas' ternyata tidak benar — koridor dan halaman juga tersedia. Menantang batasan palsu...",options:["Melanggar aturan dan membuat kelas menjadi tidak tertib","Berbahaya karena membuat peserta berani melawan setiap peraturan","Membuka ruang solusi yang tadinya tertutup tanpa alasan nyata"],answer:2,explain:"Sebagian 'batasan' hanya asumsi. Memeriksa mana yang nyata dan mana yang dibayangkan memperluas pilihan.",hint:"Apakah batasan ini benar-benar ada, atau hanya kita kira begitu?"},
{n:46,type:"mcq",micro:"Menyempurnakan lewat umpan balik",q:"Setelah menunjukkan purwarupa ke calon pengguna dan mendapat komentar, langkah kreatif:",options:["Pilih perbaikan yang paling berdampak, ubah purwarupa, uji lagi — iterasi","Abaikan komentar yang masuk karena purwarupa dibuat untuk dipamerkan","Buang ide itu dan mulai dari nol dengan topik yang sepenuhnya baru"],answer:0,explain:"Kreativitas dalam praktik adalah siklus: buat → tunjukkan → pelajari → perbaiki.",hint:"Apa yang kamu lakukan dengan komentar dari pengguna purwarupa?"},
{n:47,type:"order",micro:"Dari ide kreatif ke solusi teruji",q:"Urutkan langkah mengubah ide kreatif menjadi solusi yang bisa dipercaya.",items:["Kembangkan ide: jawab 'bagaimana persisnya ini bekerja'","Buat purwarupa atau uji coba kecil","Kumpulkan umpan balik & data, perbaiki","Putuskan: terapkan lebih luas, iterasi lagi, atau tinggalkan"],answer:[0,1,2,3],explain:"Kembangkan → purwarupa/uji → umpan balik & perbaiki → putuskan.",hint:"Ide perlu dijabarkan sebelum bisa dibuat purwarupanya."},
{n:48,type:"mcq",micro:"Mencatat ide untuk nanti",q:"Ide kreatif yang bagus tapi belum bisa dipakai sekarang sebaiknya...",options:["Dirahasiakan dari kelompok lain agar tidak ada yang meniru ide kita nantinya","Disimpan dalam 'bank ide' — bisa pas untuk masalah lain atau saat keadaan berubah","Dibuang saja sebab ide yang sudah ditolak tidak berguna lagi bagi kelompok"],answer:1,explain:"Ide yang tidak cocok hari ini bisa jadi solusi tepat besok. Menyimpannya menghemat kerja masa depan.",hint:"Apakah ide yang tak dipakai sekarang pasti tak berguna selamanya?"},
{n:49,type:"mcq",micro:"Kreativitas dalam kendala waktu",q:"Untuk masalah mendesak, versi cepat proses kreatif:",options:["Lewati kreativitas, lalu ambil ide pertama yang muncul di kepala tanpa mempertimbangkannya","Habiskan seluruh waktu untuk menghasilkan ide, tanpa menyisakan waktu memilih dan mencoba","10 menit hasilkan ide dengan 2 teknik → 5 menit saring dengan 2 kriteria → pilih & coba"],answer:2,explain:"Proses kreatif bisa dipadatkan: tetap melebar-menyempit, hanya dengan waktu yang lebih ketat.",hint:"Bisakah kamu tetap menghasilkan beberapa ide meski waktunya sempit?"},
{n:50,type:"mcq",micro:"Ide yang mengubah pertanyaan",q:"Alih-alih 'bagaimana membuat siswa mengumpulkan tugas tepat waktu', tim bertanya 'bagaimana membuat mengumpulkan tugas jadi mudah dan otomatis'. Ini contoh...",options:["Membingkai ulang menuju 'mengurangi hambatan' daripada 'menekan orang' — jenis solusi yang berbeda muncul","Menghindari masalah dengan mengganti kata-kata saja, sedangkan keadaan di lapangan tidak berubah","Pertanyaan yang salah, karena pertanyaan semacam itu terlalu lembut untuk mengubah perilaku orang"],answer:0,explain:"Mengubah pertanyaan mengubah solusi. 'Kurangi gesekan' sering lebih efektif daripada 'tambah tekanan'.",hint:"Solusi apa yang muncul dari 'permudah' vs 'paksa'?"},
{n:51,type:"open",micro:"Mengembangkan satu ide menjadi solusi",q:"Ambil ide kreatif ini: 'sudut kelas jadi 'stasiun bantuan' tempat siswa yang sudah paham membantu yang belum, bergiliran'. Kembangkan menjadi solusi: (1) bagaimana persisnya berjalan, (2) apa yang dibutuhkan, (3) bagaimana purwarupa/uji coba kecilnya, (4) 2 risiko & cara menanganinya.",explain:"Jawaban baik menjabarkan mekanisme konkret, kebutuhan, rencana uji coba kecil terukur, dan mitigasi risiko yang spesifik.",hint:"Ubah 'ide bagus' menjadi 'begini persisnya cara kerjanya, hari demi hari'.",sample:"(1) Setiap istirahat pertama, 2 siswa 'penjaga stasiun' (bergilir dari daftar) duduk di sudut dengan tanda 'Stasiun Bantuan'. Siswa lain boleh datang menanyakan materi hari itu. Sesi 10 menit, guru mengawasi dari jauh. (2) Dibutuhkan: sudut dengan 3–4 kursi, papan kecil/tanda, jadwal penjaga, daftar topik minggu ini. (3) Uji coba: jalankan 1 minggu untuk pelajaran matematika saja; catat berapa yang datang & topik apa; tanya penjaga & pengunjung apakah membantu. (4) Risiko: (a) penjaga tidak benar-benar bisa menjelaskan → sediakan 'kartu contoh soal + langkah' sebagai pegangan, dan pasangkan penjaga kuat dengan yang sedang; (b) jadi ajang mengobrol/ramai → batasi 4 orang, aturan 'satu topik selesai baru ganti', guru sesekali lewat."},
{n:52,type:"mcq",micro:"Kreativitas yang menghormati batasan nyata",q:"Ide 'ubah jam sekolah jadi siang' kreatif tapi...",options:["Tidak layak dipikirkan oleh orang lain, karena ide yang menyentuh aturan sekolah harus langsung dibuang dan tidak boleh disebut lagi","Membentur batasan nyata (transportasi, jam kerja orang tua, aturan dinas) — bisa dicatat sebagai usulan jangka panjang, bukan solusi minggu ini","Harus langsung dilakukan minggu ini, karena ide yang kreatif tidak perlu mempertimbangkan batasan seperti transportasi maupun aturan dinas"],answer:1,explain:"Membedakan batasan nyata dari batasan bayangan penting. Ide yang membentur batasan nyata besar bisa disimpan sebagai usulan, bukan tindakan segera.",hint:"Siapa saja yang terpengaruh dan harus setuju untuk ide sebesar ini?"},
{n:53,type:"tf",micro:"Menggabungkan ide sering lebih kuat",q:"Benar atau Salah: Solusi akhir yang baik sering merupakan gabungan bagian-bagian dari beberapa ide, bukan satu ide utuh yang menang telak.",answer:true,explain:"Ambil kekuatan dari beberapa ide (mekanisme dari satu, cara komunikasi dari lain) untuk menyusun solusi yang lebih lengkap.",hint:"Apakah kamu wajib memilih tepat satu ide dan membuang sisanya?"},
{n:54,type:"mcq",micro:"Kreativitas untuk masalah, bukan hanya produk",q:"Berpikir kreatif berguna untuk...",options:["Hanya untuk bidang seni dan penemuan barang baru, sehingga tidak ada gunanya bagi urusan sehari-hari di kelas","Hanya untuk anak-anak yang sedang bermain, sehingga orang dewasa dan pekerja tidak membutuhkan cara berpikir ini","Bukan hanya membuat barang baru, tapi juga menemukan cara baru mengatur, berkomunikasi, membagi tugas, atau memandang situasi"],answer:2,explain:"Kreativitas dalam proses, aturan, dan cara pandang sering lebih berdampak daripada kreativitas benda.",hint:"Apakah 'cara baru mengatur giliran' juga hasil berpikir kreatif?"},
{n:55,type:"mcq",micro:"Ketika kreativitas tidak dibutuhkan",q:"Untuk masalah yang punya prosedur standar terbukti (misalnya cara memadamkan api kecil dengan benar), yang dibutuhkan adalah...",options:["Mengikuti prosedur yang sudah terbukti — bukan menciptakan cara baru saat itu juga","Mencari cara kreatif yang baru setiap kali, termasuk dalam keadaan darurat yang berbahaya","Mengabaikan prosedur yang ada karena prosedur lama sudah ketinggalan zaman dan tak bisa dipercaya"],answer:0,explain:"Kreativitas berharga untuk masalah baru/terbuka. Untuk masalah yang solusinya sudah mapan dan bertaruh tinggi, ikuti yang terbukti.",hint:"Kapan lebih baik mengikuti aturan yang sudah teruji daripada berimprovisasi?"},
{n:56,type:"mcq",micro:"Ruang aman untuk ide",q:"Kelas menyepakati aturan sesi ide: 'tidak ada ide yang ditertawakan; semua dicatat; kritik nanti'. Aturan ini...",options:["Tidak berpengaruh pada keberanian peserta, karena rasa takut dinilai tidak ada hubungannya","Meningkatkan jumlah dan keberanian ide karena orang tidak takut dinilai saat itu juga","Membuat sesi kacau karena semua peserta berbicara tanpa ada yang memimpin atau mengatur"],answer:1,explain:"Norma yang jelas menciptakan keamanan psikologis, yang meningkatkan partisipasi dan keberanian.",hint:"Apa yang membuat orang berani mengucapkan ide setengah jadi?"},
{n:57,type:"tf",micro:"Kreativitas butuh bahan mentah",q:"Benar atau Salah: Pengetahuan tentang masalah dan bidang terkait tidak berpengaruh pada kreativitas; ide baru muncul dari kekosongan, bukan dari apa yang sudah kita ketahui.",answer:false,explain:"Kreativitas sering berupa 'menghubungkan hal yang sudah ada dengan cara baru'. Semakin banyak yang kamu tahu, semakin banyak bahan untuk dihubungkan.",hint:"Bisakah kamu menggabungkan ide dari bidang yang belum pernah kamu pelajari?"},
{n:58,type:"mcq",micro:"Ide vs eksekusi",q:"Pepatah 'ide itu murah, eksekusi yang mahal' mengingatkan bahwa...",options:["Ide tidak penting, karena nilai sebuah gagasan hanya ditentukan oleh orang yang menjalankannya","Eksekusi tidak penting, karena ide yang bagus akan berjalan dengan sendirinya setelah dipilih","Menghasilkan ide hanya awal; nilai nyata muncul saat ide dikembangkan, diuji, dan dijalankan dengan baik"],answer:2,explain:"Berpikir kreatif harus dilanjutkan dengan pengembangan dan pelaksanaan agar berdampak.",hint:"Apa yang terjadi pada ide bagus yang tidak pernah dikerjakan?"},
{n:59,type:"mcq",micro:"Menilai ide kreatif dengan adil",q:"Saat menyaring, ide yang tidak biasa sebaiknya dinilai dengan...",options:["Bertanya 'apa versi ini yang bisa dijalankan?' sebelum menolaknya — bukan langsung mencoret karena terdengar aneh","Langsung dicoret supaya daftar ide tetap ringkas dan kelompok tidak membuang waktu membahasnya","Diberi bonus nilai karena aneh, sebab ide yang paling aneh dianggap paling kreatif dan layak dipilih"],answer:0,explain:"Ide berani sering butuh 'diterjemahkan' ke versi praktis. Menolaknya mentah-mentah membuang potensi.",hint:"Apa inti berharga dari ide aneh ini, dan bagaimana mewujudkannya dengan wajar?"},
{n:60,type:"open",micro:"Kreatif + kritis untuk masalah nyata",q:"Pilih masalah nyata. Lakukan: (1) tulis 3 asumsi & tantang masing-masing, (2) hasilkan 8 ide dengan minimal 2 teknik (SCAMPER, analogi jauh, balik masalah, ekstrem waktu), (3) saring dengan 3 kriteria menjadi 2 kandidat, (4) untuk 1 kandidat, jabarkan cara kerja + rencana purwarupa/uji coba kecil.",explain:"Kapstone-lite yang menggabungkan menantang asumsi, teknik menghasilkan ide, penyaringan kritis, dan pengembangan menuju uji coba.",hint:"Jangan berhenti di daftar ide — bawa satu sampai 'begini persisnya dan begini kami mengujinya'.",sample:"Jawaban lengkap mengisi keempat bagian: asumsi yang benar-benar bisa ditantang (bukan fakta); 8 ide beragam dengan teknik ditandai; penyaringan memakai kriteria eksplisit (mis. gratis/aman/cepat) menuju 2 kandidat; dan satu kandidat dijabarkan sampai tingkat 'begini cara kerjanya + begini kami mengujinya di lingkup kecil dengan ukuran X'. Contoh domain: 'meja kelas selalu berantakan' → asumsi 'tiap siswa bertanggung jawab mejanya sendiri', 'kerapian dicek di akhir hari', 'berantakan = malas'; ide via SCAMPER (hilangkan laci berantakan → rak dinding bersama; balik → 'inspeksi acak oleh teman sebangku'); dst."},
{n:61,type:"mcq",micro:"Kreativitas vs kerumitan",q:"Tim memilih solusi paling rumit dan 'wow' padahal ada solusi sederhana yang efektif. Kesalahannya:",options:["Kesederhanaan jarang dianggap kreatif, sehingga solusi sederhana biasanya kalah dari solusi yang rumit dan megah","Menganggap 'lebih rumit & mengesankan' = 'lebih kreatif/lebih baik'; sering solusi paling elegan justru yang paling sederhana","Solusi yang rumit lebih kreatif dan lebih baik, sehingga makin rumit sebuah solusi makin tepat dipilih kelas"],answer:1,explain:"Kreativitas sejati sering menghasilkan kesederhanaan yang tidak terlihat sebelumnya, bukan kerumitan yang mengesankan.",hint:"Apakah ide yang paling rumit otomatis paling kreatif?"},
{n:62,type:"tf",micro:"Tidak semua ide baru itu baik",q:"Benar atau Salah: Sebuah ide bisa sangat orisinal dan tetap merupakan solusi yang buruk karena tidak layak, tidak adil, atau menimbulkan masalah lebih besar.",answer:true,explain:"Kebaruan bukan jaminan kualitas. Ide kreatif tetap harus lolos uji kelayakan, keadilan, dan efek samping.",hint:"Apakah 'belum pernah dicoba' berarti 'ide bagus'?"},
{n:63,type:"mcq",micro:"Kreativitas yang mengabaikan pengguna",q:"Solusi 'kreatif' yang dirancang tanpa bertanya pada orang yang akan memakainya berisiko...",options:["Berhasil karena kreatif, sehingga pengguna otomatis menyesuaikan diri dengan rancangan itu","Tidak berisiko, sebab solusi yang rumit dan canggih sulit ditolak oleh pengguna","Terasa pintar bagi perancang tapi tidak cocok dengan kebutuhan/kebiasaan nyata pengguna"],answer:2,explain:"Kreativitas paling berguna kalau berangkat dari pemahaman nyata tentang orang yang dilayani.",hint:"Siapa yang akan memakai solusi ini, dan apakah mereka ditanya?"},
{n:64,type:"mcq",micro:"Kapan berhenti mencari ide",q:"Tanda kamu sudah cukup menghasilkan ide dan waktunya menyaring:",options:["Ide-ide baru mulai berupa variasi tipis dari yang sudah ada, dan kamu punya cukup ragam untuk memilih","Setelah tiga ide pertama, karena ide-ide selanjutnya jarang lebih baik daripada ide awal kelompok","Ketika sebagian anggota sudah bosan, karena rasa bosan menandakan seluruh ide telah habis"],answer:0,explain:"Ketika 'hasil berkurang' terjadi (ide baru hanya sedikit berbeda), fase melebar sudah cukup.",hint:"Apakah ide ke-25 benar-benar berbeda dari ide ke-20, atau hanya variasi?"},
{n:65,type:"mcq",micro:"Bias 'ide milikku'",q:"Kamu menilai idemu sendiri lebih tinggi dari ide setara milik orang lain. Cara mengurangi bias ini:",options:["Buang ide milik orang lain supaya penilaianmu tidak terpengaruh","Nilai ide tanpa nama pengusul, atau minta orang lain menilai idemu","Pilih idemu sendiri karena kamu paling memahami manfaatnya bagi kelas"],answer:1,explain:"Menyembunyikan asal ide saat penilaian membuat fokus pada isi, bukan siapa yang mengusulkan.",hint:"Apa yang membuat penilaian lebih adil terhadap ide orang lain?"},
{n:66,type:"tf",micro:"Kreativitas dalam tim butuh mendengarkan",q:"Benar atau Salah: Dalam sesi ide kelompok, orang yang paling banyak bicara hampir selalu yang punya ide terbaik, jadi cukup mendengarkan mereka.",answer:false,explain:"Ide bagus tersebar merata. Memberi ruang bagi yang jarang bicara — lewat menulis ide sendiri dulu atau bergiliran — sering memunculkan ide yang terlewat.",hint:"Apakah volume suara sama dengan kualitas ide?"},
{n:67,type:"mcq",micro:"Kreativitas semu (mengikuti tren)",q:"Memilih solusi hanya karena 'sekolah lain sedang melakukannya' atau 'terdengar kekinian'...",options:["Ide terbaik, karena ide yang sudah dipakai orang lain tentu terbukti berhasil di tempat kita","Cara yang aman, sebab meniru tidak memerlukan pemikiran dan tidak mungkin menimbulkan masalah","Bukan berpikir kreatif — itu meniru tanpa memeriksa apakah cocok untuk masalah dan konteks kita"],answer:2,explain:"Meniru bisa jadi titik awal (adaptasi), tapi menyalin tanpa pemeriksaan kecocokan bukan kreativitas dan sering gagal.",hint:"Apakah solusi ini dipilih karena cocok untuk kita, atau karena sedang populer?"},
{n:68,type:"mcq",micro:"Risiko 'terlalu terikat pada ide favorit'",q:"Setelah punya ide yang kamu sukai, terus mencari alternatif dan bersedia meninggalkannya bila ada yang lebih baik adalah...",options:["Tanda pemikir yang matang — ide adalah alat, bukan identitas yang harus dibela","Ketidaksetiaan pada ide sendiri, sehingga pemikir yang baik harus membela idenya","Buang-buang waktu, sebab ide yang sudah dipilih tidak perlu ditinjau lagi"],answer:0,explain:"Keterikatan berlebihan pada satu ide menutup mata terhadap yang lebih baik. Pegang ide dengan longgar.",hint:"Apakah kamu membela ide karena ia terbaik, atau karena ia milikmu?"},
{n:69,type:"mcq",micro:"Kreativitas dan kesetaraan akses",q:"Solusi 'kreatif' yang butuh smartphone / internet / biaya bisa...",options:["Tidak jadi masalah, sebab siswa yang tertinggal dapat mengejar sendiri dari rumah masing-masing nanti","Meninggalkan sebagian siswa yang tidak punya akses; solusi inklusif mempertimbangkan siapa yang mungkin tersisih","Lebih baik karena modern, sehingga para siswa akan terdorong membeli sendiri perangkat yang diperlukan"],answer:1,explain:"Kreativitas yang baik memeriksa: apakah semua orang yang perlu memakai solusi ini bisa mengaksesnya?",hint:"Siapa yang mungkin tidak bisa ikut kalau solusinya butuh alat tertentu?"},
{n:70,type:"order",micro:"Menilai sebuah ide kreatif",q:"Urutkan pertanyaan untuk menilai apakah ide kreatif layak dilanjutkan.",items:["Apakah ide ini benar-benar mengatasi masalah aslinya (bukan hanya terdengar menarik)?","Apakah bisa dijalankan dengan sumber daya nyata & dalam batasan yang ada?","Apakah adil dan bisa diakses oleh semua yang perlu memakainya?","Apa efek samping / masalah baru yang mungkin muncul?"],answer:[0,1,2,3],explain:"Mengatasi masalah? layak? adil & inklusif? efek samping? — sebelum berkomitmen mengembangkannya.",hint:"Mulai dari 'apakah ini benar-benar menyelesaikan masalahnya'."},
{n:71,type:"mcq",micro:"Kreativitas di bawah tekanan",q:"Saat panik atau sangat lelah, kemampuan berpikir kreatif cenderung...",options:["Meningkat — pikiran makin tajam karena kelelahan memaksa otak mencari jalan pintas yang lebih baru","Tidak terpengaruh — kreativitas hanya bergantung pada bakat dan tidak berubah oleh keadaan tubuh","Menurun — pikiran menyempit ke jalur yang paling dikenal; jeda singkat atau tidur cukup membantu memulihkannya"],answer:2,explain:"Stres tinggi mempersempit pemikiran. Untuk masalah yang butuh kreativitas, kondisi tenang dan istirahat penting.",hint:"Kapan ide-ide segar lebih sering datang: saat panik atau saat tenang?"},
{n:72,type:"mcq",micro:"Kreativitas vs disiplin",q:"Hubungan antara kreativitas dan kerja keras yang disiplin:",options:["Saling melengkapi — kreativitas menghasilkan arah, disiplin mewujudkannya lewat pengembangan dan pengujian berulang","Bertentangan satu sama lain sehingga seseorang harus memilih salah satu saja: menjadi kreatif atau menjadi disiplin","Kreativitas menggantikan kerja keras sepenuhnya, sebab ide yang bagus pasti terwujud tanpa perlu usaha dan pengujian"],answer:0,explain:"Ide brilian tanpa kerja keras tetap ide. Kerja keras tanpa kreativitas bisa mengerjakan hal yang salah dengan rajin.",hint:"Apa yang dibutuhkan setelah ide bagus muncul?"},
{n:73,type:"tf",micro:"Kreativitas bukan hanya untuk 'orang kreatif'",q:"Benar atau Salah: Setiap orang bisa berlatih dan menggunakan teknik berpikir kreatif; ini bukan sifat yang hanya dimiliki sebagian orang sejak lahir.",answer:true,explain:"Menantang asumsi, berganti perspektif, dan menggabungkan ide adalah keterampilan yang bisa diajarkan dan dilatih siapa saja.",hint:"Apakah teknik seperti SCAMPER hanya bisa dipakai 'orang berbakat'?"},
{n:74,type:"mcq",micro:"Ide yang menyalahi nilai",q:"Ide 'kreatif' untuk menang lomba kebersihan: 'sembunyikan sampah di kelas lain'. Ini gugur karena...",options:["Kurang orisinal karena idenya sudah pernah dipakai oleh orang lain sebelumnya","Melanggar kejujuran & merugikan orang lain — kreativitas harus tetap dalam batas etika","Terlalu berani bagi sekolah, sehingga idenya perlu dikecilkan agar lebih aman"],answer:1,explain:"Kreativitas yang mencapai tujuan dengan cara yang tidak jujur atau merugikan orang lain bukan solusi yang baik.",hint:"Apakah 'berhasil' dengan cara curang benar-benar berhasil?"},
{n:75,type:"mcq",micro:"Menyeimbangkan orisinalitas dan yang terbukti",q:"Untuk sebagian masalah, jawaban terbaik adalah solusi standar yang sudah terbukti; untuk sebagian lain, dibutuhkan pendekatan baru. Cara membedakan:",options:["Buat solusi baru dari nol untuk semua masalah, bahkan masalah umum yang sudah punya cara penyelesaian terbukti di banyak sekolah lain","Pakai solusi lama yang sudah ada untuk semua masalah, bahkan ketika solusi itu terbukti tidak berhasil pada keadaan khas kelas kita","Kalau masalahnya umum & solusinya mapan → pakai yang terbukti; kalau masalahnya khas konteks kita / solusi lama tidak jalan → butuh kreativitas"],answer:2,explain:"Kreativitas adalah alat untuk saat yang tepat, bukan keharusan di setiap masalah.",hint:"Apakah masalah ini benar-benar baru, atau sudah sering dipecahkan orang?"},
{n:76,type:"mcq",micro:"Kreativitas yang tidak diuji",q:"Ide kreatif yang langsung diterapkan luas tanpa uji coba kecil berisiko...",options:["Kalau ada cacat tak terduga, dampaknya besar dan mahal diperbaiki; uji kecil dulu mengurangi risiko ini","Tidak ada risiko kalau idenya bagus, sebab ide yang baik tidak mungkin punya cacat tersembunyi","Berhasil karena skala besar membuat seluruh pihak sekolah langsung terlibat sejak hari pertama"],answer:0,explain:"Ide baru punya lebih banyak ketidakpastian. Menguji di lingkup kecil sebelum skala penuh adalah kehati-hatian yang bijak.",hint:"Kapan lebih murah menemukan cacat ide: di uji coba atau setelah diterapkan ke semua?"},
{n:77,type:"tf",micro:"Kreativitas berkembang dari keberagaman masukan",q:"Benar atau Salah: Orang yang membaca luas, mengalami hal beragam, dan berbicara dengan orang berlatar berbeda cenderung punya lebih banyak bahan untuk koneksi kreatif.",answer:true,explain:"Kreativitas sering berupa menggabungkan hal-hal yang sudah ada. Semakin beragam yang kamu tahu, semakin banyak kombinasi yang mungkin.",hint:"Dari mana datangnya bahan mentah untuk ide baru?"},
{n:78,type:"mcq",micro:"Menghargai proses meski hasil belum kreatif",q:"Sesi ide menghasilkan banyak ide biasa dan tidak ada yang 'brilian'. Sikap yang tepat:",options:["Berhenti mencoba berpikir kreatif, karena hasil yang biasa menunjukkan bahwa kelompok tidak berbakat","Tetap berharga — ide biasa bisa digabung/dikembangkan, dan latihan itu sendiri memperkuat kebiasaan kreatif","Sesi itu gagal total dan harus dihapus dari catatan, sebab ide biasa tidak mungkin dikembangkan menjadi solusi"],answer:1,explain:"Tidak setiap sesi menghasilkan terobosan. Kombinasi dan pengembangan ide biasa sering cukup, dan latihan membangun keterampilan.",hint:"Apakah nilai sesi ide hanya dari 'ide brilian', atau juga dari bahan dan latihannya?"},
{n:79,type:"mcq",micro:"Kreativitas dan rendah hati",q:"Setelah menemukan ide yang kamu anggap hebat, kebiasaan yang menyehatkan:",options:["Hanya bercerita kepada orang yang akan memujinya, supaya semangatmu tetap tinggi","Rahasiakan idemu sampai diterapkan, supaya tak ada yang menunjukkan kekurangannya","Cari orang yang bisa menunjukkan kelemahannya, dan dengarkan dengan sungguh-sungguh"],answer:2,explain:"Ide menjadi lebih kuat setelah diuji oleh kritik yang jujur. Mencari kelemahan lebih awal lebih baik daripada menemukannya saat sudah terlambat.",hint:"Siapa yang sebaiknya kamu tunjukkan idemu — pemuji atau penantang?"},
{n:80,type:"open",micro:"Membedakan ide kreatif yang baik dari yang menyesatkan",q:"Untuk masalah 'kelas kekurangan dana kegiatan', dua ide muncul: (A) 'jual makanan buatan siswa saat istirahat'; (B) 'setiap siswa wajib menyetor Rp20.000, yang tidak bayar tidak boleh ikut kegiatan'. Keduanya 'menyelesaikan' masalah dana. Analisis: mana yang lebih baik dan mengapa, memakai kriteria kelayakan, keadilan, efek samping, dan keberlanjutan.",explain:"Jawaban baik memakai keempat kriteria untuk menunjukkan bahwa ide yang 'menyelesaikan masalah dana' bisa buruk kalau tidak adil, merusak hubungan, dan tidak berkelanjutan.",hint:"'Menyelesaikan masalah utama' saja tidak cukup — periksa siapa yang menanggung biayanya dan apa efek sampingnya.",sample:"A lebih baik. Kelayakan: keduanya bisa dijalankan, tapi A tidak membebani siapa pun secara paksa. Keadilan: B menghukum siswa dari keluarga kurang mampu dan menciptakan pembagian 'yang boleh ikut' vs 'tidak' — tidak adil; A mengumpulkan dana dari penjualan sukarela ke pembeli. Efek samping: B merusak kebersamaan kelas dan bisa mempermalukan siswa; A justru bisa membangun kerja sama dan keterampilan (memasak, berjualan, mengelola uang). Keberlanjutan: A bisa diulang; B hanya sekali dan meninggalkan rasa tidak enak. Kesimpulan: A. Perbaikan untuk A: buat jadwal & pembagian tugas adil, mulai kecil, catat untung-rugi."},
{n:81,type:"mcq",micro:"Membingkai ulang masalah besar",q:"Kota menghadapi 'jalan macet'. Membingkai ulang sebagai 'terlalu banyak orang perlu bergerak pada waktu yang sama dengan cara yang memakan banyak ruang' membuka solusi seperti...",options:["Transportasi bersama, jam kerja/sekolah bergeser, jalur sepeda, bekerja dari rumah sebagian — bukan hanya 'lebarkan jalan'","Hanya pelebaran jalan, karena kemacetan berasal dari jalan yang kurang lebar dan tidak punya sebab lain di kota","Larang semua kendaraan pribadi masuk ke dalam kota, tanpa menyiapkan pengganti bagi warga yang bekerja setiap hari"],answer:0,explain:"Membingkai ulang masalah dari 'kurang jalan' menjadi 'pola pergerakan' memunculkan jenis solusi yang jauh lebih beragam.",hint:"Kalau masalahnya bukan 'kurang aspal', apa solusinya?"},
{n:82,type:"mcq",micro:"Kreativitas untuk kendala yang tampak mustahil",q:"'Kita butuh panggung tapi tidak ada dana dan tidak boleh mengubah aula.' Berpikir kreatif menanyakan...",options:["Langgar saja aturan aula dengan membuat panggung sementara dari kursi dan meja yang ditumpuk tinggi, karena fungsi panggung hanya dianggap soal ketinggian dan tidak ada cara lain mencapainya","Apa fungsi sebenarnya dari 'panggung' (terlihat & terdengar oleh penonton)? Bisakah dicapai tanpa panggung fisik — misalnya penonton duduk melingkar, pemain di tengah, dengan level dari kursi/meja aman?","Batalkan acara itu sekarang juga dan ganti dengan kegiatan lain yang tidak memerlukan panggung maupun penonton, karena aula tidak mengizinkan panggung dipasang di dalamnya oleh panitia"],answer:1,explain:"Kembali ke FUNGSI yang dibutuhkan (bukan bentuk yang biasa) sering membuka jalan saat bentuk biasa terhalang.",hint:"Apa yang sebenarnya harus dicapai 'panggung', dan adakah cara lain mencapainya?"},
{n:83,type:"tf",micro:"Kreativitas kolektif untuk masalah besar",q:"Benar atau Salah: Untuk masalah kompleks yang menyangkut banyak orang, satu orang yang berpikir sendiri biasanya menghasilkan solusi yang lebih baik dan lebih diterima daripada proses yang melibatkan beragam pihak.",answer:false,explain:"Beragam sudut pandang menangkap lebih banyak aspek masalah, dan keterlibatan pihak yang terdampak membangun dukungan untuk pelaksanaan.",hint:"Siapa yang perlu dilibatkan agar solusi cocok DAN didukung?"},
{n:84,type:"mcq",micro:"Kombinasi kreatif untuk solusi berlapis",q:"Untuk 'siswa kurang bergerak saat istirahat', solusi kreatif yang kuat mungkin menggabungkan...",options:["Satu aturan wajib olahraga untuk seluruh siswa pada setiap jam istirahat, tanpa pilihan lain dan tanpa permainan, sebagai satu 'program besar' saja","Tidak melakukan apa-apa, karena siswa kurang bergerak adalah keputusan mereka sendiri dan bukan urusan sekolah ataupun urusan pihak lain","Beberapa ide kecil: tanda permainan di lantai koridor + kotak alat main pinjam + 5 menit gerak bersama sebelum masuk — bukan satu 'program besar'"],answer:2,explain:"Masalah perilaku sering paling baik ditangani dengan beberapa dorongan kecil yang saling menguatkan.",hint:"Apakah satu 'program besar' atau beberapa 'dorongan kecil' lebih mungkin mengubah kebiasaan?"},
{n:85,type:"order",micro:"Proses kreatif lengkap untuk masalah kompleks",q:"Urutkan langkah menghasilkan solusi kreatif untuk masalah kompleks.",items:["Pahami masalah dari beberapa sudut pandang & tuliskan asumsi","Bingkai ulang masalah dengan 2–3 cara berbeda","Hasilkan banyak ide untuk tiap bingkai, pakai beberapa teknik","Saring dengan kriteria (layak/adil/efek samping/berkelanjutan), gabungkan yang saling melengkapi, kembangkan & uji kecil"],answer:[0,1,2,3],explain:"Pahami multi-sudut → bingkai ulang → hasilkan ide per bingkai → saring, gabungkan, kembangkan, uji.",hint:"Membingkai ulang datang setelah memahami, sebelum menghasilkan ide."},
{n:86,type:"mcq",micro:"Kreativitas dan data",q:"Ide kreatif untuk 'perpustakaan sepi' menjadi lebih tajam kalau didahului...",options:["Data ringan: kapan sepi, siapa yang datang & tidak, apa yang mereka cari — agar ide menyasar penyebab nyata","Tidak perlu data, langsung saja berkreasi sebanyak mungkin karena data hanya membatasi imajinasi kelompok","Data mematikan kreativitas, sehingga ide-ide terbaik hanya muncul kalau kita tidak tahu apa penyebab masalahnya"],answer:0,explain:"Kreativitas dan bukti bukan musuh. Memahami masalah lewat data membuat ide kreatif lebih tepat sasaran.",hint:"Ide untuk 'menarik siapa, kapan, untuk apa' — bagaimana kamu tahu tanpa melihat data?"},
{n:87,type:"mcq",micro:"Menjaga kreativitas dalam organisasi yang sudah mapan",q:"Panitia yang sudah bertahun-tahun memakai format acara yang sama bisa menyegarkan ide dengan...",options:["Melarang perubahan format sesi dan mempertahankan anggota lama saja, supaya ide-ide tetap sejalan dan tidak membingungkan","Sengaja mengundang anggota baru/dari luar untuk sesi ide, dan bertanya 'kalau kita mulai dari nol hari ini, apa yang akan kita buat?'","Terus memakai format lama karena sudah terbukti aman, serta tidak mengundang orang baru supaya suasana sesi tetap nyaman"],answer:1,explain:"Perspektif segar dan pertanyaan 'mulai dari nol' menembus 'kita selalu begini' yang membekukan kreativitas.",hint:"Bagaimana menembus kebiasaan 'sudah bertahun-tahun begini'?"},
{n:88,type:"tf",micro:"Ide kreatif tetap perlu rencana pelaksanaan",q:"Benar atau Salah: Setelah ide kreatif dipilih, ia tetap harus diterjemahkan menjadi rencana konkret (langkah, penanggung jawab, sumber daya, jadwal) agar benar-benar berdampak.",answer:true,explain:"Kreativitas menghasilkan arah; pelaksanaan yang terencana mewujudkannya. Keduanya dibutuhkan.",hint:"Apa yang mengubah 'ide bagus yang dipilih' menjadi 'sesuatu yang benar-benar terjadi'?"},
{n:89,type:"mcq",micro:"Kreativitas etis",q:"Prinsip yang menjaga kreativitas tetap bertanggung jawab:",options:["Boleh melakukan apa saja asalkan berhasil, termasuk menipu atau merugikan pihak lain selama tujuan akhirnya tercapai","Kreativitas bebas dari semua aturan etika, sehingga ide yang berbahaya pun tetap boleh dijalankan selama menarik","Solusi kreatif tidak boleh mencapai tujuan dengan menipu, merugikan pihak lain secara tidak adil, atau mengorbankan keselamatan"],answer:2,explain:"Kebebasan berpikir dalam menghasilkan ide tetap dibatasi oleh kejujuran, keadilan, dan keselamatan saat memilih dan melaksanakan.",hint:"Apakah ide yang 'berhasil' dengan cara curang benar-benar solusi yang baik?"},
{n:90,type:"mcq",micro:"Membedakan hambatan kreativitas",q:"Kelas kesulitan menghasilkan ide segar. Kemungkinan penyebab dan penanganannya:",options:["Takut dinilai → buat aturan ruang aman; kurang bahan/pengetahuan → beri contoh & info dulu; terjebak satu bingkai → bingkai ulang masalah","Kelas itu memang tidak kreatif dari sananya, sehingga ide segar tidak akan pernah muncul meskipun sudah dicoba dengan berbagai cara dan teknik yang ada","Kelas itu sulit ditolong oleh siapa saja, sebab kemampuan berpikir kreatif tidak bisa dilatih oleh guru ataupun oleh teman sekelasnya"],answer:0,explain:"Kebuntuan kreatif punya penyebab yang bisa diidentifikasi dan ditangani — bukan sifat tetap.",hint:"Apa yang berbeda antara 'takut bicara', 'tidak punya bahan', dan 'terpaku satu cara pandang'?"},
{n:91,type:"mcq",micro:"Kreativitas untuk peluang, bukan hanya masalah",q:"Berpikir kreatif juga berguna untuk...",options:["Hanya untuk keadaan darurat yang mendadak, ketika semua cara biasa sudah gagal dan tidak ada pilihan lain lagi","Melihat peluang: 'apa yang bisa kita buat lebih baik / ciptakan / mulai', bukan hanya memperbaiki yang rusak","Hanya untuk memperbaiki masalah yang sudah rusak, bukan untuk menciptakan sesuatu yang baru dan lebih baik"],answer:1,explain:"Kreativitas proaktif — merancang kegiatan baru, meningkatkan yang sudah baik, memulai hal bermanfaat — sama pentingnya dengan kreativitas reaktif.",hint:"Apakah kreativitas hanya untuk 'ada yang salah', atau juga untuk 'bisa lebih baik'?"},
{n:92,type:"tf",micro:"Berpikir kreatif melengkapi keterampilan lain",q:"Benar atau Salah: Berpikir kreatif adalah pengganti keterampilan pemecahan masalah yang lain, sehingga kalau kamu kreatif kamu tidak lagi perlu memahami masalah, merencanakan, atau mengevaluasi.",answer:false,explain:"Kreativitas bukan pengganti — ia memperkaya setiap tahap (terutama menghasilkan pilihan dan membingkai ulang) dan bekerja paling baik bersama pemahaman masalah, dekomposisi, penilaian kritis, perencanaan, dan evaluasi.",hint:"Apakah kreativitas cukup sendirian untuk menyelesaikan masalah dari awal sampai akhir?"},
{n:93,type:"mcq",micro:"Menilai keberhasilan solusi kreatif",q:"Solusi kreatif dievaluasi dengan standar yang sama seperti solusi lain:",options:["Standar khusus yang lebih longgar, karena ide kreatif tidak adil bila dinilai dengan cara yang sama seperti lainnya","Tidak perlu dievaluasi karena idenya sudah bagus, sehingga hasilnya terjamin mengatasi masalah","Apakah masalah aslinya berkurang? Terhadap kriteria & baseline. Efek samping? Untuk siapa berhasil?"],answer:2,explain:"Kebaruan ide tidak memberi keringanan dalam evaluasi. Bukti keberhasilan tetap diperlukan.",hint:"Apakah 'idenya kreatif' menggantikan 'buktikan bahwa ini berhasil'?"},
{n:94,type:"open",micro:"Berpikir kreatif untuk masalah kompleks nyata",q:"Pilih masalah kompleks nyata (di sekolah/lingkungan) yang solusi biasanya tidak menyelesaikannya. Lakukan: (1) pahami dari 3 sudut pandang berbeda, (2) tuliskan & tantang 3 asumsi, (3) bingkai ulang masalah dengan 2 cara, (4) hasilkan 10 ide (min. 3 teknik), (5) saring & gabungkan menjadi 1 solusi berlapis, (6) jabarkan cara kerja + rencana uji coba kecil + 2 risiko & mitigasinya.",explain:"Kapstone: multi-perspektif, menantang asumsi (dari 'kesadaran' ke 'desain sistem'), membingkai ulang ke 'kurangi di sumber', ide beragam, solusi berlapis, dan uji coba terukur dengan mitigasi risiko.",hint:"Kunci sering di membingkai ulang: kalau bingkainya 'kesadaran siswa', solusinya poster lagi; kalau bingkainya 'desain sistem', solusinya berbeda total.",sample:"Contoh domain: 'sampah plastik di kantin terus banyak meski sudah ada tempat sampah pilah dan poster'. (1) Sudut: siswa (buru-buru, tidak sempat memilah), penjual (kemasan sekali pakai paling murah & praktis), petugas kebersihan (pilahan tercampur lagi saat diangkut). (2) Asumsi: 'masalahnya kesadaran siswa', 'pilah di tempat sampah adalah solusinya', 'penjual tidak mau berubah'. Tantang: mungkin masalahnya DESAIN sistem, bukan kesadaran; mungkin mengurangi sampah di sumber lebih efektif daripada memilah di ujung; penjual mau berubah kalau tidak rugi. (3) Bingkai ulang: 'bagaimana mengurangi plastik sekali pakai MASUK ke kantin' dan 'bagaimana membuat pilihan tanpa-plastik jadi yang paling mudah'. (4) Ide via SCAMPER/balik/ekstrem: bawa wadah sendiri dapat diskon; kantin sedia gelas/piring pakai-ulang dengan deposit; menu 'tanpa kemasan' (makan di tempat); kerja sama penjual beli kemasan kertas grosir agar murah; 'hari tanpa plastik' mingguan; petugas 'duta wadah' bergilir; dst. (5) Solusi berlapis: (a) kantin sediakan piring/gelas pakai-ulang + sistem deposit koin; (b) diskon Rp1.000 untuk yang bawa wadah; (c) 1 hari/minggu 'tanpa kemasan sekali pakai' sebagai transisi. (6) Uji coba: jalankan (a)+(b) di satu kios selama 2 minggu; ukur berat sampah plastik kios itu vs kios lain; hitung berapa siswa pakai wadah/piring ulang. Risiko: piring ulang hilang/tidak dikembalikan → sistem deposit + tempat pengembalian jelas; penjual rugi → sekolah subsidi awal piring + hitung ulang setelah 2 minggu."},
{n:95,type:"mcq",micro:"Kreativitas dan iterasi",q:"Solusi kreatif jarang sempurna di percobaan pertama. Yang membuatnya akhirnya berhasil biasanya...",options:["Beberapa putaran perbaikan berdasarkan umpan balik nyata dari uji coba","Ide awal yang cukup brilian sehingga tidak perlu diubah, walau sudah diuji","Berhenti setelah percobaan pertama, karena yang berikutnya sama saja"],answer:0,explain:"Kreativitas + iterasi: ide awal memberi arah, uji coba dan perbaikan berulang membawanya ke bentuk yang benar-benar bekerja.",hint:"Apa yang terjadi antara 'ide pertama' dan 'solusi yang benar-benar berhasil'?"},
{n:96,type:"mcq",micro:"Menularkan kebiasaan kreatif",q:"Cara sebuah kelompok menjadi lebih kreatif dari waktu ke waktu:",options:["Melarang ide aneh dalam setiap sesi, supaya waktu kelompok dipakai hanya untuk ide yang masuk akal","Membiasakan ritual: menantang asumsi di awal tiap masalah, ruang aman untuk ide, meninjau apa yang berhasil","Menunggu anggota yang berbakat bergabung ke kelompok, sebab kreativitas tidak bisa dilatih sendiri"],answer:1,explain:"Kreativitas kelompok tumbuh dari kebiasaan dan norma yang dipelihara, bukan dari keberuntungan memiliki 'orang jenius'.",hint:"Apa yang bisa dijadikan kebiasaan rutin untuk menjaga kreativitas kelompok?"},
{n:97,type:"tf",micro:"Kreativitas paling berharga saat solusi biasa gagal",q:"Benar atau Salah: Berpikir kreatif memberi nilai terbesar justru pada masalah di mana pendekatan standar sudah dicoba dan tidak menyelesaikannya.",answer:true,explain:"Untuk masalah yang solusi biasanya mempan, ikuti yang terbukti. Kreativitas adalah alat untuk saat jalan yang biasa buntu.",hint:"Kapan kamu paling butuh 'cara berpikir baru'?"},
{n:98,type:"mcq",micro:"Menutup: kreatif dan bertanggung jawab",q:"Berpikir kreatif yang matang menggabungkan...",options:["Hanya keberanian menghasilkan ide yang sangat tidak biasa, tanpa perlu menilai kelayakan, keadilan, efek samping, ataupun menguji dan memperbaikinya lagi","Hanya kehati-hatian dalam menilai dan menolak, sehingga ide yang belum terbukti aman tak sempat dicoba, diuji, ataupun diperbaiki","Keberanian menghasilkan ide tak biasa DENGAN kejujuran menilai kelayakan, keadilan, efek samping, dan kesediaan menguji serta memperbaiki"],answer:2,explain:"Kreativitas yang bertanggung jawab: bebas saat menghasilkan, ketat dan jujur saat menilai dan melaksanakan.",hint:"Apa dua sisi yang harus seimbang?"},
{n:99,type:"mcq",micro:"Ringkasan: berpikir kreatif & alternatif",q:"Rangkuman paling tepat:",options:["Tantang asumsi, bingkai ulang masalah, ganti perspektif, dan pakai teknik (SCAMPER, analogi, balik, ekstrem) untuk menghasilkan banyak pilihan — sambil menunda penilaian; lalu saring, gabungkan, kembangkan, dan uji dengan kriteria kelayakan, keadilan, dan efek samping","Cari ide seaneh mungkin lalu langsung dipakai begitu saja, tanpa menantang asumsi, mengganti sudut pandang, menunda penilaian, menyaring, menggabungkan, ataupun mengujinya dengan kriteria kelayakan, keadilan, dan efek samping yang mungkin muncul","Kreativitas hanya untuk orang yang berbakat sejak lahir dan hanya muncul secara kebetulan, sehingga sebagian besar anak tidak perlu mencobanya, tidak perlu mempelajari teknik lain, dan cukup memakai cara lama yang sudah ada di sekolah mereka"],answer:0,explain:"Berpikir kreatif = memperluas pilihan lewat menantang asumsi & teknik, menunda penilaian, lalu menyempit lewat penilaian yang jujur dan pengujian.",hint:"Gabungkan: tantang asumsi + teknik + tunda penilaian → saring, gabung, uji."},
{n:100,type:"open",micro:"Kapstone: dari kebuntuan ke terobosan",q:"Pilih masalah yang membuatmu (atau kelompokmu) merasa buntu — di mana kamu terus memikirkan solusi yang sama dan tidak puas. Lakukan seluruh proses kreatif: (1) tulis solusi 'default' yang selalu kamu pikirkan & mengapa tidak memuaskan, (2) identifikasi 3 asumsi yang mungkin mengunci pemikiranmu & tantang, (3) bingkai ulang masalah 2 cara, (4) hasilkan 12 ide baru (min. 4 teknik), (5) pilih 2 kandidat yang benar-benar berbeda dari solusi default, (6) kembangkan salah satunya jadi rencana uji coba kecil dengan ukuran keberhasilan.",explain:"Kapstone menuntut bukti bahwa berpikir kreatif menghasilkan pilihan yang benar-benar berbeda dari 'yang selalu dipikirkan', lengkap dengan menantang asumsi, membingkai ulang, dan rencana uji terukur.",hint:"Kunci bagian (2): apa yang selama ini kamu anggap 'harus begitu' padahal sebenarnya bisa lain?",sample:"Jawaban lengkap menunjukkan pergeseran nyata dari solusi default. Contoh: masalah 'sulit fokus belajar di rumah'; default 'coba lebih disiplin / matikan HP' yang tidak memuaskan karena 'sudah dicoba, gagal berulang'. Asumsi: 'aku harus belajar sendirian di kamar', 'belajar berarti duduk diam berjam-jam', 'gangguan ada di HP saja'. Tantang: belajar bersama teman via panggilan bisa membuat akuntabel; sesi pendek 20 menit + jeda mungkin lebih cocok; gangguan juga dari rasa bosan/tidak tahu mulai dari mana. Bingkai ulang: 'bagaimana membuat mulai belajar jadi mudah' dan 'bagaimana membuat 20 menit fokus, bukan 3 jam'. Ide: teknik pomodoro dengan timer; 'ruang belajar bersama' online dengan 2 teman; siapkan tugas malam sebelumnya jadi tinggal mulai; belajar di ruang keluarga (bukan kamar) di jam tertentu; hadiah kecil tiap 4 sesi; mulai dengan soal termudah untuk membangun momentum; dst. Kandidat berbeda dari default: (A) sesi 20 menit terjadwal + belajar bersama teman via panggilan; (B) menyiapkan 'paket mulai' tugas setiap sore. Kembangkan A: uji 1 minggu, ukur jumlah sesi 20 menit yang benar-benar selesai per hari (target rata-rata 4) dan penilaian fokus sendiri 1–5."},
];
